<div class="ps-chat" data-chat-widget>
    <button class="ps-chat-toggle" type="button" data-chat-toggle aria-expanded="false" aria-controls="ps-chat-panel" aria-label="Mở PhoneStore AI"><i class="bi bi-stars"></i></button>
    <section id="ps-chat-panel" class="ps-chat-panel" data-chat-panel hidden aria-label="PhoneStore AI">
        <header class="ps-chat-header"><strong><i class="bi bi-stars"></i> PhoneStore AI</strong><button type="button" class="btn-close btn-close-white" data-chat-close aria-label="Đóng"></button></header>
        <div class="ps-chat-messages" data-chat-messages role="log" aria-live="polite"><div class="ps-chat-message ai">Xin chào! Tôi có thể giúp bạn tìm điện thoại dựa trên sản phẩm thật của PhoneStore.</div></div>
        <div class="ps-chat-suggestions" data-chat-suggestions><button type="button">Dưới 5 triệu</button><button type="button">Chơi game tốt</button><button type="button">Chụp ảnh đẹp</button><button type="button">Pin trâu</button></div>
        <form class="ps-chat-form" data-chat-form><label class="visually-hidden" for="ps-chat-input">Câu hỏi</label><input id="ps-chat-input" name="message" maxlength="1000" autocomplete="off" placeholder="Bạn đang cần tìm gì?" required><button class="ps-btn-primary" type="submit" aria-label="Gửi"><i class="bi bi-send"></i></button></form>
    </section>
</div>
